Câu 2: (0.5 điểm) Cho một chương trình như sau:
#include <iostream>
using namespace std;
int main(){
    int x = 8, y = 3;
    switch(x % y){
        case 2: y--;
        default: y *= 6;
        case 0:
            x = (y == 64 ? y - x : x - y);
            break;
        case 1: y /= 2;
        case 3: x %= 3;
    }
    cout << y << x;
    return 0;
}

